let myShader;

let vertSrc = `
#ifdef GL_ES
precision highp float;
#endif

attribute vec3 aPosition;
attribute vec2 aTexCoord;

varying vec2 vTexCoord;

void main() {
    vTexCoord = aTexCoord;
    vec4 positionVec4 = vec4(aPosition, 1.0);
    positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
    gl_Position = positionVec4;
}
`;

let fragSrc = `
#ifdef GL_ES
precision highp float;
#endif

uniform vec2 iResolution;
uniform float iTime;

varying vec2 vTexCoord;

float tanh_approx(float x) {
    x = clamp(x, -3.0, 3.0);
    float x2 = x * x;
    return x * (27.0 + x2) / (27.0 + 9.0 * x2);
}

vec3 orangePalette(float t) {
    vec3 col0 = vec3(0.0, 0.0, 0.0);
    vec3 col1 = vec3(0.5, 0.1, 0.0);
    vec3 col2 = vec3(0.992, 0.318, 0.031);
    vec3 col3 = vec3(0.996, 0.486, 0.224);
    vec3 col4 = vec3(1.000, 0.667, 0.447);
    vec3 col5 = vec3(1.000, 0.804, 0.659);
    vec3 col6 = vec3(1.000, 0.910, 0.831);
    vec3 col7 = vec3(1.000, 0.961, 0.929);

    t = clamp(t, 0.0, 1.0);
    float idx = t * 7.0;

    if (idx < 1.0) return mix(col0, col1, idx);
    if (idx < 2.0) return mix(col1, col2, idx - 1.0);
    if (idx < 3.0) return mix(col2, col3, idx - 2.0);
    if (idx < 4.0) return mix(col3, col4, idx - 3.0);
    if (idx < 5.0) return mix(col4, col5, idx - 4.0);
    if (idx < 6.0) return mix(col5, col6, idx - 5.0);
    return mix(col6, col7, idx - 6.0);
}

void main() {
    vec2 uv = vTexCoord * 2.0 - 1.0;

    float scale = 1.0;
    uv.x *= scale * iResolution.x / iResolution.y;
    uv.y *= scale;

    const int MAX_STEPS = 25;
    const int NOISE_ITERATIONS = 7;
    const float INITIAL_OFFSET = 0.1;
    const float RADIAL_SCALE = 5.0;
    const float DEPTH_ATTENUATION = 0.2;

    float rayDepth = 0.0;
    float stepDistance = 0.0;

    vec4 finalColor = vec4(0.0);

    vec3 rayDirection = normalize(vec3(uv, 1.0));

    for (int step = 0; step < MAX_STEPS; step++) {
        vec3 position = rayDepth * rayDirection + INITIAL_OFFSET;

        float angle = atan(position.y / 0.2, position.x) * 2.0;
        float radius = length(position.xy) - RADIAL_SCALE - rayDepth * DEPTH_ATTENUATION;
        float height = position.z / 3.0;
        position = vec3(angle, height, radius);

        for (int noiseStep = 1; noiseStep <= NOISE_ITERATIONS; noiseStep++) {
            float noiseScale = float(noiseStep);
            vec3 noiseInput = position.yzx * noiseScale + iTime + 0.3 * float(step);
            position += sin(noiseInput) / noiseScale;
        }

        vec3 surfacePattern = 0.4 * cos(position) - 0.4;
        stepDistance = length(vec4(surfacePattern, position.z));
        rayDepth += stepDistance;

        float colorPhase = position.x + float(step) * 0.4 + rayDepth;
        vec4 colorPattern = vec4(6.0, 1.0, 9.0, 0.0);
        finalColor += (1.0 + cos(colorPhase + colorPattern)) / stepDistance;
    }

    vec4 processed = finalColor * finalColor / 400.0;
    processed.r = tanh_approx(processed.r);
    processed.g = tanh_approx(processed.g);
    processed.b = tanh_approx(processed.b);

    float brightness = max(processed.r, max(processed.g, processed.b));

    float colorVariation = processed.r * 0.5 + processed.g * 0.3 + processed.b * 0.2;
    colorVariation = clamp(colorVariation, 0.0, 1.0);

    vec3 finalRGB = orangePalette(colorVariation) * brightness;

    finalRGB = pow(finalRGB, vec3(0.85));

    gl_FragColor = vec4(finalRGB, 1.0);
}
`;

function setup() {
  pixelDensity(displayDensity());
 createCanvas(windowWidth, windowHeight, WEBGL);
  noStroke();
  myShader = createShader(vertSrc, fragSrc);
}

function draw() {
  shader(myShader);
  myShader.setUniform('iResolution', [width * displayDensity(), height * displayDensity()]);
  myShader.setUniform('iTime', millis() / 1000.0);
  rect(0, 0, width, height);
}

